function fixtureMsg(
  chatId: string,
  role: ChatMessage["role"],
  content: string,
  model: string | null,
  meta?: ChatMessage["meta"],
): ChatMessage {
  fixtureSeq += 1;
  return {
    id: `fxmsg_${fixtureSeq}`,
    seq: fixtureSeq,
    role,
